INSERT INTO "Category" ("id", "slug", "name", "parentId", "family", "position", "published", "createdAt", "updatedAt")
SELECT 'amc' || substr(md5('c:' || c.s), 1, 22), c.s, c.n, par."id", c.f::"PartFamily", c.o, true, NOW(), NOW()
FROM "_amp_cat" c LEFT JOIN "Category" par ON par."slug" = c.p
ON CONFLICT ("slug") DO NOTHING;

