INSERT INTO "ProductVariant" ("id", "productId", "sku", "name", "packaging", "priceCents", "vatRateId", "stockOnHand",
  "position", "createdAt", "updatedAt")
SELECT x.id, x.p, x.sku, x.n, x.k::"Packaging", x.c, (SELECT "id" FROM "VatRate" WHERE "code" = 'FR_STANDARD'), 10, x.o, NOW(), NOW()
FROM "_amp_v" x JOIN "Product" p ON p."id" = x.p
ON CONFLICT DO NOTHING;

INSERT INTO "StockMovement" ("id", "variantId", "delta", "reason", "reference", "createdAt")
SELECT 'ams' || substr(md5('m:' || v."id"), 1, 22), v."id", 10, 'import', 'catalogue:ampoules', NOW()
FROM "_amp_v" x JOIN "ProductVariant" v ON v."id" = x.id
ON CONFLICT ("id") DO NOTHING;

